          <div style="background:var(--nixie-bg);border:1px solid var(--nixie-edge);border-radius:3px;padding:8px 12px;box-shadow:inset 0 0 10px rgba(0,0,0,0.85);font-family:var(--f-tube);font-size:14px;color:var(--nixie);text-shadow:0 0 3px var(--nixie),0 0 9px rgba(255,138,61,0.5);letter-spacing:0.1em">V${c(i.version||"?")} \xB7 LOCAL</div>
